import{_ as n,o as a,c as i,a2 as e}from"./chunks/framework.BgftbQsK.js";const o=JSON.parse('{"title":"Understanding the Linux Filesystem","description":"Deep dive into Linux directory structure (/bin, /etc, /home, /var, /dev), device files concept, and file permissions (chmod, chown, numeric modes).","frontmatter":{"title":"Understanding the Linux Filesystem","order":4,"description":"Deep dive into Linux directory structure (/bin, /etc, /home, /var, /dev), device files concept, and file permissions (chmod, chown, numeric modes).","head":[["meta",{"name":"og:title","content":"Understanding the Linux Filesystem | Ubuntu Home Lab Server"}],["meta",{"property":"og:description","content":"Deep dive into Linux directory structure (/bin, /etc, /home, /var, /dev), device files concept, and file permissions (chmod, chown, numeric modes)."}]]},"headers":[],"relativePath":"chapters/04-understanding-the-linux-filesystem.md","filePath":"chapters/04-understanding-the-linux-filesystem.md","lastUpdated":null}'),p={name:"chapters/04-understanding-the-linux-filesystem.md"};function l(t,s,r,h,d,k){return a(),i("div",null,[...s[0]||(s[0]=[e(`<h2 id="the-directory-structure-explained" tabindex="-1">The Directory Structure Explained <a class="header-anchor" href="#the-directory-structure-explained" aria-label="Permalink to &quot;The Directory Structure Explained&quot;">​</a></h2><p>In Linux, everything starts from <code>/</code> (root). Unlike Windows with <code>C:\\</code>, <code>D:\\</code>, there&#39;s only one tree:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/</span></span>
<span class="line"><span>├── bin/        → Essential user commands (ls, cp, mv, cat...)</span></span>
<span class="line"><span>├── boot/       → Kernel and bootloader files</span></span>
<span class="line"><span>├── dev/        → Device files (your disks, USB, GPU are here!)</span></span>
<span class="line"><span>├── etc/        → ALL system configuration files (text files)</span></span>
<span class="line"><span>├── home/       → User home directories (/home/labadmin)</span></span>
<span class="line"><span>├── lib/        → Shared libraries (like .dll files in Windows)</span></span>
<span class="line"><span>├── media/      → Auto-mounted removable media (USB drives)</span></span>
<span class="line"><span>├── mnt/        → Manual mount points</span></span>
<span class="line"><span>├── opt/        → Optional software (some apps install here)</span></span>
<span class="line"><span>├── proc/       → Virtual filesystem — info about running processes</span></span>
<span class="line"><span>├── root/       → Home directory of the root user</span></span>
<span class="line"><span>├── run/        → Runtime data (PIDs, sockets)</span></span>
<span class="line"><span>├── srv/        → Service data (your apps go here)</span></span>
<span class="line"><span>├── sys/        → Virtual filesystem — hardware info</span></span>
<span class="line"><span>├── tmp/        → Temporary files (cleared on reboot)</span></span>
<span class="line"><span>├── usr/        → User programs and data</span></span>
<span class="line"><span>│   ├── bin/    → Most user commands</span></span>
<span class="line"><span>│   ├── lib/    → Libraries</span></span>
<span class="line"><span>│   └── local/  → Locally installed software</span></span>
<span class="line"><span>└── var/        → Variable runtime data</span></span>
<span class="line"><span>    ├── log/    → Log files</span></span>
<span class="line"><span>    ├── lib/    → Application state data</span></span>
<span class="line"><span>    └── cache/  → Cached data</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br></div></div><h2 id="the-dev-directory-—-everything-is-a-file" tabindex="-1">The <code>/dev</code> Directory — Everything is a File <a class="header-anchor" href="#the-dev-directory-—-everything-is-a-file" aria-label="Permalink to &quot;The \`/dev\` Directory — Everything is a File&quot;">​</a></h2><p>This concept is unique to Unix/Linux and very powerful. Hardware devices are represented as files:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/dev/nvme0n1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">      →</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Your</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Samsung</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> NVMe</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> SSD</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/dev/nvme0n1p1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    →</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> First</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> partition</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> on</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> the</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> NVMe</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/dev/sda</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">          →</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Your</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> WD</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> HDD</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/dev/sda1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">         →</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> First</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> partition</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> on</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> the</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> HDD</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/dev/sdb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">          →</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Your</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> USB</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> drive</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/dev/null</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">         →</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> The</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> black</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hole</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> —</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> anything</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> written</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> here</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> disappears</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/dev/random</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">       →</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Random</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> number</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> generator</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/dev/tty</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">          →</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Current</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> terminal</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p>This means you can interact with hardware using standard file operations:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Copy an ISO directly to a USB drive (using it as a file!)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> if=ubuntu.iso</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> of=/dev/sdb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bs=4M</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Check disk health by &quot;reading&quot; the device</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hdparm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -I</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/sda</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Wipe a disk by writing zeros to it</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> if=/dev/zero</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> of=/dev/sda</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bs=1M</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> count=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">100</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><h2 id="file-permissions-—-the-most-important-linux-concept" tabindex="-1">File Permissions — The Most Important Linux Concept <a class="header-anchor" href="#file-permissions-—-the-most-important-linux-concept" aria-label="Permalink to &quot;File Permissions — The Most Important Linux Concept&quot;">​</a></h2><p>Every file in Linux has three permission sets: <strong>owner</strong>, <strong>group</strong>, and <strong>others</strong>. Each set has three permissions: <strong>read (r)</strong>, <strong>write (w)</strong>, <strong>execute (x)</strong>.</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ls</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -la</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/nginx/nginx.conf</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># -rw-r--r-- 1 root root 1447 May 19 10:00 nginx.conf</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#  │││││││││</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#  │││││││└─ others: r-- (read only)</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#  │││││└──── group: r-- (read only)</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#  │││└─────── owner: rw- (read + write)</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#  ││└──────── type: - (regular file), d (directory), l (symlink)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Change permissions</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 755</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> script.sh</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # owner: rwx, group: r-x, others: r-x</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 644</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config.txt</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # owner: rw-, group: r--, others: r--</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +x</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy.sh</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # add execute permission for everyone</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Change owner</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> chown</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> labadmin:labadmin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /srv/myapp</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> chown</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -R</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> labadmin:labadmin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /srv/</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # -R = recursive</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p>Numeric permissions:</p><ul><li><code>7</code> = rwx (4+2+1)</li><li><code>6</code> = rw- (4+2)</li><li><code>5</code> = r-x (4+1)</li><li><code>4</code> = r-- (4)</li><li><code>0</code> = --- (nothing)</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p><strong>Security rule:</strong> Never use <code>chmod 777</code>. It gives everyone full access. Use the minimum permissions needed.</p></div>`,15)])])}const F=n(p,[["render",l]]);export{o as __pageData,F as default};
